{
  "name": "@forget2save/opencode-goal-mode",
  "version": "0.2.0",
  "description": "A persistent, budgeted Goal mode plugin for OpenCode.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "coding-agent",
    "goal-mode",
    "agent"
  ],
  "license": "MIT",
  "scripts": {
    "clean": "node scripts/clean.mjs",
    "check": "tsc --noEmit",
    "test": "bun test test",
    "build": "npm run clean && tsc -p tsconfig.build.json",
    "smoke": "node scripts/plugin-smoke.mjs",
    "verify": "bun run check && bun test test && bun run build && node scripts/plugin-smoke.mjs",
    "prepack": "npm run verify"
  },
  "dependencies": {
    "@opencode-ai/plugin": ">=1.16.0 <1.19.0"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "latest"
  },
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  }
}
